from math import *
def f(x):
    return 1-sin(x)
def pt_fixe():
    x=0.1
    i=0
    while abs(f(x)-x)>0.00001:
        x=f(x)
        i=i+1
    print("Le nombre d'iteration est: ",i)
    return x
#Programme Principale
print(pt_fixe())

